  "footer.scrolltop": { en: "↑ Back to top", es: "↑ Volver arriba", ja: "↑ トップへ戻る" },
  "footer.text": { en: "Part of <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Chapter 17: Panel Data, Time Series, and Causality · by Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>", es: "Parte de <a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a> · Capítulo 17: Datos de panel, series de tiempo y causalidad · por Carlos Mendez · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>", ja: "<a href=\"https://quarcs-lab.github.io/metricsai/book/_book/index.html\"><strong>metricsAI</strong></a>の一部 · 第17章：パネルデータ、時系列、因果性 · Carlos Mendez著 · <a href=\"https://github.com/quarcs-lab/metricsai\">GitHub</a>" },
  "header.badge": { en: "Chapter 17 of 18 · Interactive Dashboard", es: "Capítulo 17 de 18 · Tablero interactivo", ja: "第17章 / 全18章 · インタラクティブ・ダッシュボード" },
  "header.subtitle": { en: "Explore between vs within variation, compare standard errors, watch fixed effects remove bias, and see how first differencing cures spurious regression — using NBA revenue and U.S. interest rate data.", es: "Explora la variación entre vs intra, compara errores estándar, observa cómo los efectos fijos eliminan el sesgo, y descubre cómo la primera diferencia cura la regresión espuria — usando datos de ingresos de la NBA y tasas de interés de EE. UU.", ja: "グループ間とグループ内の変動を比較し、標準誤差を見比べ、固定効果がバイアスを取り除く様子を観察し、一階差分が見せかけの回帰をどう解消するかを確認します — NBAの収益データと米国の金利データを用いて。" },
  "meta.title": { en: "Chapter 17 — Panel Data, Time Series, and Causality · metricsAI", es: "Capítulo 17 — Datos de panel, series de tiempo y causalidad · metricsAI", ja: "第17章 — パネルデータ、時系列、因果性 · metricsAI" },
